diff --git a/internal/server/routes_links.go b/internal/server/routes_links.go
new file mode 100644
index 0000000..a0e5b74
--- /dev/null
+++ b/internal/server/routes_links.go
@@ -0,0 +1,206 @@
+package server
+
+import (
+	"crypto/rand"
+	"encoding/json"
+	"errors"
+	"io"
+	"net/http"
+	"net/url"
+	"strings"
+	"time"
+
+	"git.aisoftwarefactory.world/linkshort3/linkshort3/internal/store"
+)
+
+// The link card's limits, from the spec: a target is an http or https URL of
+// at most maxTargetLen characters, a custom slug is [a-z0-9-]{3,32}, and a
+// user may create at most newLinksPerHour links per hour.
+const (
+	maxTargetLen    = 2048
+	slugMinLen      = 3
+	slugMaxLen      = 32
+	autoSlugLen     = 7
+	newLinksPerHour = 30
+	// maxLinkBody is the JSON a create request may carry: a 2048-character
+	// target, a 32-character slug and the syntax around them.
+	maxLinkBody = 4096
+)
+
+// slugAlphabet is what an auto-generated slug is built from: the characters a
+// custom slug allows, so a generated one reads the same as a chosen one.
+const slugAlphabet = "abcdefghijklmnopqrstuvwxyz0123456789-"
+
+// linkJSON is a link as the API speaks it. created_at is UTC RFC 3339.
+type linkJSON struct {
+	Slug        string `json:"slug"`
+	URL         string `json:"url"`
+	TotalClicks int64  `json:"clicks"`
+	CreatedAt   string `json:"created_at"`
+}
+
+func init() {
+	addRoutes(func(s *Server) {
+		s.HandleFunc("POST /api/links", s.createLink)
+		s.HandleFunc("GET /api/links", s.listLinks)
+		s.HandleFunc("DELETE /api/links/{slug}", s.deleteLink)
+	})
+}
+
+// createLink shortens a URL for the logged-in user: 400 for a body that is not
+// JSON or names no acceptable URL, 429 when the hour's quota is used up, 409
+// when the slug is taken and 201 with the new link otherwise.
+func (s *Server) createLink(w http.ResponseWriter, r *http.Request) {
+	userID, ok := requireUser(w, r)
+	if !ok {
+		return
+	}
+	body, err := readLinkBody(r)
+	if err != nil {
+		writeError(w, http.StatusBadRequest)
+		return
+	}
+	var req struct {
+		URL  string `json:"url"`
+		Slug string `json:"slug"`
+	}
+	if err := json.Unmarshal(body, &req); err != nil {
+		writeError(w, http.StatusBadRequest)
+		return
+	}
+	target, ok := validTargetURL(req.URL)
+	if !ok {
+		writeError(w, http.StatusBadRequest)
+		return
+	}
+	slug := strings.TrimSpace(req.Slug)
+	if slug == "" {
+		if slug, err = randomSlug(); err != nil {
+			writeError(w, http.StatusInternalServerError)
+			return
+		}
+	} else if !validSlug(slug) {
+		writeError(w, http.StatusBadRequest)
+		return
+	}
+	count, err := s.store.CountNewLinksByUserSince(r.Context(), userID, time.Now().UTC().Add(-time.Hour))
+	if err != nil {
+		writeError(w, http.StatusInternalServerError)
+		return
+	}
+	if count >= newLinksPerHour {
+		writeError(w, http.StatusTooManyRequests)
+		return
+	}
+	link := &store.Link{UserID: userID, Slug: slug, TargetURL: target, CreatedAt: time.Now().UTC()}
+	switch err := s.store.CreateLink(r.Context(), link); {
+	case errors.Is(err, store.ErrDuplicate):
+		writeError(w, http.StatusConflict)
+	case err != nil:
+		writeError(w, http.StatusInternalServerError)
+	default:
+		writeJSON(w, http.StatusCreated, linkOut(link))
+	}
+}
+
+// listLinks answers the logged-in user's own links, newest first, each with
+// its total click count.
+func (s *Server) listLinks(w http.ResponseWriter, r *http.Request) {
+	userID, ok := requireUser(w, r)
+	if !ok {
+		return
+	}
+	links, err := s.store.ListLinksByUser(r.Context(), userID)
+	if err != nil {
+		writeError(w, http.StatusInternalServerError)
+		return
+	}
+	out := make([]linkJSON, 0, len(links))
+	for _, l := range links {
+		out = append(out, linkOut(l))
+	}
+	writeJSON(w, http.StatusOK, out)
+}
+
+// deleteLink forgets one of the user's own links; a slug that is not there or
+// belongs to someone else answers 404, which tells the caller nothing about
+// whether the link exists.
+func (s *Server) deleteLink(w http.ResponseWriter, r *http.Request) {
+	userID, ok := requireUser(w, r)
+	if !ok {
+		return
+	}
+	slug := r.PathValue("slug")
+	switch err := s.store.DeleteLink(r.Context(), userID, slug); {
+	case errors.Is(err, store.ErrNotFound):
+		writeError(w, http.StatusNotFound)
+	case err != nil:
+		writeError(w, http.StatusInternalServerError)
+	default:
+		w.WriteHeader(http.StatusNoContent)
+	}
+}
+
+func linkOut(l *store.Link) linkJSON {
+	return linkJSON{
+		Slug:        l.Slug,
+		URL:         l.TargetURL,
+		TotalClicks: l.TotalClicks,
+		CreatedAt:   l.CreatedAt.UTC().Format(time.RFC3339),
+	}
+}
+
+// readLinkBody is the create request's JSON, capped so that a huge body costs
+// nothing but the bytes already sent.
+func readLinkBody(r *http.Request) ([]byte, error) {
+	defer func() { _ = r.Body.Close() }()
+	return io.ReadAll(http.MaxBytesReader(nil, r.Body, maxLinkBody))
+}
+
+// validTargetURL accepts an absolute http or https URL with a host of at most
+// maxTargetLen characters, and returns it trimmed.
+func validTargetURL(raw string) (string, bool) {
+	raw = strings.TrimSpace(raw)
+	if raw == "" || len(raw) > maxTargetLen {
+		return "", false
+	}
+	u, err := url.Parse(raw)
+	if err != nil || !u.IsAbs() || u.Host == "" {
+		return "", false
+	}
+	scheme := strings.ToLower(u.Scheme)
+	if scheme != "http" && scheme != "https" {
+		return "", false
+	}
+	return raw, true
+}
+
+// validSlug reports whether a custom slug is [a-z0-9-]{3,32}. It need not read
+// as a domain label: the spec allows "-", including leading and trailing.
+func validSlug(slug string) bool {
+	if len(slug) < slugMinLen || len(slug) > slugMaxLen {
+		return false
+	}
+	for i := 0; i < len(slug); i++ {
+		c := slug[i]
+		if c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || c == '-' {
+			continue
+		}
+		return false
+	}
+	return true
+}
+
+// randomSlug is autoSlugLen characters of crypto/rand over slugAlphabet. A
+// clash with an existing slug is the store's 409 answer, not retried here.
+func randomSlug() (string, error) {
+	buf := make([]byte, autoSlugLen)
+	if _, err := rand.Read(buf); err != nil {
+		return "", err
+	}
+	slug := make([]byte, autoSlugLen)
+	for i, b := range buf {
+		slug[i] = slugAlphabet[int(b)%len(slugAlphabet)]
+	}
+	return string(slug), nil
+}

