diff --git a/internal/server/routes_links_test.go b/internal/server/routes_links_test.go
new file mode 100644
index 0000000..5ea06a8
--- /dev/null
+++ b/internal/server/routes_links_test.go
@@ -0,0 +1,298 @@
+package server_test
+
+import (
+	"context"
+	"encoding/json"
+	"io"
+	"net/http"
+	"strings"
+	"testing"
+	"time"
+
+	"git.aisoftwarefactory.world/linkshort3/linkshort3/internal/server"
+	"git.aisoftwarefactory.world/linkshort3/linkshort3/internal/store"
+)
+
+// newLinksServer serves the app over one store, and returns it with a session
+// token of its own, so that a test can name whose link is whose.
+func newLinksServer(t *testing.T) (*httptestServer, store.Store) {
+	t.Helper()
+	st, err := store.Open(t.TempDir())
+	if err != nil {
+		t.Fatal(err)
